# owner: platform
"""Find the stretches of opening hours that nobody is covering."""

from typing import Iterable, List

from hourglass.errors import ProjectError
from hourglass.merging import merge_spans
from hourglass.models import Span
from hourglass.parsing import format_clock


def find_gaps(worked: Iterable[Span], opening: Span) -> List[str]:
    """One label such as 'gap 12:00-13:00 (60 min)' per uncovered stretch."""
    spans = list(worked)
    for span in spans:
        if span.start < opening.start or span.end > opening.end:
            raise ProjectError(
                "span {}-{} is outside opening hours".format(
                    format_clock(span.start), format_clock(span.end)
                )
            )

    labels = []
    cursor = opening.start
    for span in merge_spans(spans):
        if span.start > cursor:
            labels.append(_label(cursor, span.start))
        cursor = span.end
    if cursor < opening.end:
        labels.append(_label(cursor, opening.end))
    return labels


def _label(start: int, end: int) -> str:
    return "gap {}-{} ({} min)".format(
        format_clock(start), format_clock(end), end - start
    )
EOF
cat > tests/test_gaps.py <<'EOF'
# owner: platform
import unittest

from hourglass.errors import ProjectError
from hourglass.gaps import find_gaps
from hourglass.parsing import parse_span


class FindGapsTests(unittest.TestCase):
    def setUp(self):
        self.opening = parse_span("09:00-17:00")

    def test_gap_in_the_middle(self):
        worked = [parse_span("09:00-12:00"), parse_span("13:00-17:00")]
        self.assertEqual(
            find_gaps(worked, self.opening), ["gap 12:00-13:00 (60 min)"]
        )

    def test_gaps_at_both_ends(self):
        worked = [parse_span("10:00-16:00")]
        self.assertEqual(
            find_gaps(worked, self.opening),
            ["gap 09:00-10:00 (60 min)", "gap 16:00-17:00 (60 min)"],
        )

    def test_overlaps_leave_no_gap(self):
        worked = [parse_span("09:00-14:00"), parse_span("13:00-17:00")]
        self.assertEqual(find_gaps(worked, self.opening), [])

    def test_nobody_working(self):
        self.assertEqual(
            find_gaps([], self.opening), ["gap 09:00-17:00 (480 min)"]
        )

    def test_span_outside_opening_hours(self):
        with self.assertRaises(ProjectError):
            find_gaps([parse_span("08:00-12:00")], self.opening)
EOF
